package java_world;

public class Math_min {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int x=3;
		int y=4;
		System.out.println(Math.max(x, y)); //which no. is maximum b/w 2 given no.
		System.out.println(Math.min(x, y)); //which no. is minimum b/w 2 given no.
		System.out.println(Math.pow(8, 2)); //find the power of given no.
		System.out.println(Math.sqrt(81)); //find the square root of given no.
		System.out.println(Math.cbrt(8)); //find the cube root of given no.
		System.out.println(Math.abs(-8)); //find the absolute value of given no.
		System.out.println(Math.round(8.4)); //find the round off value of given no.
		//****System.out.println(Math.rint(9.1)); //find the nearest even integer of given no.
		System.out.println(Math.ceil(5.5)); //find the ceiling(next) of given no.
		System.out.println(Math.floor(5.5)); //find the floor(previous) of given no.
		System.out.println(Math.sin(8)); //find the sin of given no.
		System.out.println(Math.cos(8)); //find the cos of given no.
		System.out.println(Math.tan(8)); //find the tan of given no.
		System.out.println(Math.random()); //find a random no.

	} 

}
